#!/bin/bash
# The 100-board panel specialist batch (resumable: finished boards are skipped); stops its actors when done.
cd /home/eric/Desktop/prog/catan/catanatron/catanatron-rs/python
.venv/bin/python -u specialists.py --boards runs/boards/panel100.json --prefix sp3 --base-pt runs/o3/model.pt --base-net runs/o3/o3_187.ctnn --max-iters 20 --success 2.0 --eval-every 10 --eval-games 1000 --threads 8 -- --openhex-1v1 --opponent-hands --opponent-devs --extra-info --spot-features --games 2 --sims-full 400 --sims-fast 50 --sims-placement 2400 --c-puct 1.0 --fpu 0.25 --lr 2e-4 --replay 200000 --replay-device cpu --min-replay 20000 --threads 2 --device cuda --bf16 --endgame-vp 13 --endgame-branches 1 --opening-branches 1 --placement-forks 1 --placement-temp 2.0 --placement-uniform 0.25 --opening-share 0.1 --luck --margin-weight 0.1 --speed-weight 0.3 --speed-turns 150 --aux-weight 0.5 --value-q-weight 0.25 --hidden 512 --layers 4 --minutes 600 --remote-bucket catanselfplay-bucket83908e77-vusaorgcj8uf --remote-control-key models/control_sp3.json --remote-games-per-core 4 --remote-max-shards 2 --remote-max-lag 8 >> runs/sp3.out 2>&1
for t in $(aws ecs describe-tasks --cluster catan-selfplay --tasks $(aws ecs list-tasks --cluster catan-selfplay --query 'taskArns' --output text) --query 'tasks[?contains(overrides.containerOverrides[0].command[3], `control_sp3`)].taskArn' --output text); do aws ecs stop-task --cluster catan-selfplay --task $t --reason 'panel specialists done' >/dev/null; done
echo sp3-done >> runs/sp3.out
